package ec.edu.monster.consulta; import ec.edu.monster.dto.Peticiones; import ec.edu.monster.modelo.*; import ec.edu.monster.servicio.*; import jakarta.ws.rs.*; import jakarta.ws.rs.core.MediaType; import java.util.*; @Path("") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) public class ConsultaResource {private final BancoService b=new BancoService();private final AdminService a=new AdminService();@GET @Path("clientes") public List<ClienteResumen> clientes(){return b.clientes();}@POST @Path("clientes") public Resultado cliente(Peticiones.NuevoCliente p){return a.cliente(p.getPaterno(),p.getMaterno(),p.getNombre(),p.getDni(),p.getCiudad(),p.getDireccion(),p.getTelefono(),p.getEmail());}@GET @Path("cuentas") public List<CuentaResumen> cuentas(@QueryParam("cliente")String c){return b.cuentas(c);}@GET @Path("cuentas/{cuenta}/saldo") public Resultado saldo(@PathParam("cuenta")String c){return b.saldo(c);}@POST @Path("cuentas") public Resultado cuenta(Peticiones.NuevaCuenta p){return a.cuenta(p.getCliente(),p.getMoneda());}@DELETE @Path("cuentas/{cuenta}") public Resultado eliminar(@PathParam("cuenta")String c){return a.eliminar(c);}@GET @Path("movimientos") public List<MovimientoModel> movimientos(@QueryParam("cuenta")String c){return b.movimientos(c);}}
